create or replace function public.reporting_next_run(p_cadence text,p_hour integer,p_timezone text,p_day_of_week integer default null,p_day_of_month integer default null,p_from timestamptz default now()) returns timestamptz language plpgsql security definer set search_path=public,pg_temp as $$ declare local_now timestamp; candidate timestamp; i integer:=0; target_dow integer; target_dom integer; begin local_now:=timezone(coalesce(nullif(p_timezone,''),'UTC'),p_from); candidate:=date_trunc('day',local_now)+make_interval(hours=>p_hour); if p_cadence='daily' then if candidate<=local_now then candidate:=candidate+interval '1 day'; end if; elsif p_cadence='weekly' then target_dow:=coalesce(p_day_of_week,extract(dow from local_now)::integer); candidate:=date_trunc('day',local_now)+make_interval(hours=>p_hour); while extract(dow from candidate)::integer<>target_dow or candidate<=local_now loop candidate:=candidate+interval '1 day'; i:=i+1; exit when i>8; end loop; elsif p_cadence='monthly' then target_dom:=greatest(1,least(coalesce(p_day_of_month,extract(day from local_now)::integer),31)); candidate:=date_trunc('month',local_now)+make_interval(days=>target_dom-1,hours=>p_hour); if candidate<=local_now then candidate:=date_trunc('month',local_now+interval '1 month')+make_interval(days=>target_dom-1,hours=>p_hour); end if; else candidate:=candidate+interval '1 day'; end if; return candidate at time zone coalesce(nullif(p_timezone,''),'UTC'); end; $$;
create or replace function public.reporting_build_payload(p_scope_type text,p_scope_id uuid,p_start timestamptz,p_end timestamptz) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if p_scope_type='business' then select jsonb_build_object('scope','business','period_start',p_start,'period_end',p_end,'locations',(select count(*) from locations where business_id=p_scope_id and is_active),'location_views',(select count(*) from analytics_events where business_id=p_scope_id and event_type='location_view' and created_at between p_start and p_end),'unique_visitors',(select count(distinct user_id) from analytics_events where business_id=p_scope_id and user_id is not null and created_at between p_start and p_end),'check_ins',(select count(*) from check_ins c join locations l on l.id=c.location_id where l.business_id=p_scope_id and c.checked_in_at between p_start and p_end),'reviews',(select count(*) from reviews r join locations l on l.id=r.location_id where l.business_id=p_scope_id and r.created_at between p_start and p_end),'promotion_redemptions',(select count(*) from promotion_redemptions pr join promotions p on p.id=pr.promotion_id where p.business_id=p_scope_id and pr.redeemed_at between p_start and p_end),'attributed_engagements',(select count(*) from business_engagement_attributions where business_id=p_scope_id and created_at between p_start and p_end),'growth_signals',(select count(*) from business_growth_signals where business_id=p_scope_id and created_at between p_start and p_end)) into v;
elsif p_scope_type='fleet' then select jsonb_build_object('scope','fleet','period_start',p_start,'period_end',p_end,'active_vehicles',(select count(*) from fleet_vehicles where business_id=p_scope_id and status='active'),'active_drivers',(select count(*) from fleet_drivers where business_id=p_scope_id and status='active'),'routes_completed',(select count(*) from fleet_routes where business_id=p_scope_id and status='completed' and updated_at between p_start and p_end),'open_alerts',(select count(*) from fleet_alerts where business_id=p_scope_id and status='open'),'maintenance_due',(select count(*) from fleet_vehicle_daily_metrics where business_id=p_scope_id and maintenance_due),'miles',(select coalesce(sum(miles),0) from fleet_vehicle_daily_metrics where business_id=p_scope_id and metric_date between p_start::date and p_end::date),'trips',(select coalesce(sum(trips),0) from fleet_vehicle_daily_metrics where business_id=p_scope_id and metric_date between p_start::date and p_end::date),'avg_utilization_pct',(select round(avg(utilization_pct),2) from fleet_vehicle_daily_metrics where business_id=p_scope_id and metric_date between p_start::date and p_end::date)) into v;
elsif p_scope_type='enterprise' then select jsonb_build_object('scope','enterprise','period_start',p_start,'period_end',p_end,'networks',(select count(*) from enterprise_partner_networks where id=p_scope_id and enabled),'partners',(select count(*) from enterprise_partner_network_members where network_id=p_scope_id and status='active'),'campaigns',(select count(*) from enterprise_partner_campaigns where network_id=p_scope_id),'visits',(select coalesce(sum(visits),0) from enterprise_partner_network_metrics where network_id=p_scope_id and metric_date between p_start::date and p_end::date),'check_ins',(select coalesce(sum(check_ins),0) from enterprise_partner_network_metrics where network_id=p_scope_id and metric_date between p_start::date and p_end::date),'reviews',(select coalesce(sum(reviews),0) from enterprise_partner_network_metrics where network_id=p_scope_id and metric_date between p_start::date and p_end::date),'preferred_uses',(select coalesce(sum(preferred_uses),0) from enterprise_partner_network_metrics where network_id=p_scope_id and metric_date between p_start::date and p_end::date),'promotion_redemptions',(select coalesce(sum(promotion_redemptions),0) from enterprise_partner_network_metrics where network_id=p_scope_id and metric_date between p_start::date and p_end::date)) into v;
else select jsonb_build_object('scope','admin','period_start',p_start,'period_end',p_end,'profiles',(select count(*) from profiles),'locations',(select count(*) from locations where is_active),'feature_events',(select count(*) from data_feature_events where created_at between p_start and p_end),'feature_access_events',(select count(*) from feature_access_events where created_at between p_start and p_end),'notifications',(select count(*) from notifications where created_at between p_start and p_end),'open_data_conflicts',(select count(*) from location_data_conflicts where status='open'),'external_import_jobs',(select count(*) from external_import_jobs where created_at between p_start and p_end),'capability_audit_runs',(select count(*) from capability_audit_runs where executed_at between p_start and p_end)) into v; end if; return coalesce(v,'{}'::jsonb); end; $$;
create or replace function public.run_due_reporting_schedules(p_requested_by uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare s record; r_id uuid; payload jsonb; period_start timestamptz; processed integer:=0; next_run timestamptz; recipient uuid; begin if p_requested_by is null and session_user not in ('postgres','supabase_admin') then raise exception 'internal reporting execution only'; end if; for s in select * from reporting_schedules where enabled and (next_run_at is null or next_run_at<=now()) and (p_requested_by is null or owner_id=p_requested_by) order by next_run_at nulls first limit 50 loop if not pg_try_advisory_xact_lock(hashtext('reporting:'||s.id::text)) then continue; end if; period_start:=case when s.cadence='daily' then now()-interval '1 day' when s.cadence='weekly' then now()-interval '7 days' else now()-interval '1 month' end; insert into reporting_runs(schedule_id,status,period_start,period_end) values(s.id,'running',period_start,now()) returning id into r_id; begin payload:=reporting_build_payload(s.scope_type,s.scope_id,period_start,now()); update reporting_runs set status='sent',report_payload=payload,delivered_to=s.recipients,completed_at=now() where id=r_id; insert into notifications(user_id,type,title,body,data) values(s.owner_id,'scheduled_report',s.name,'Your '||s.cadence||' '||s.scope_type||' report is ready.',jsonb_build_object('report_run_id',r_id,'scope_type',s.scope_type,'scope_id',s.scope_id,'metrics',payload,'recipients',s.recipients)); next_run:=reporting_next_run(s.cadence,s.hour_local,s.timezone,s.day_of_week,s.day_of_month,now()); update reporting_schedules set last_run_at=now(),next_run_at=next_run,updated_at=now() where id=s.id; processed:=processed+1; exception when others then update reporting_runs set status='failed',error=sqlerrm,completed_at=now() where id=r_id; update reporting_schedules set next_run_at=reporting_next_run(s.cadence,s.hour_local,s.timezone,s.day_of_week,s.day_of_month,now()+interval '1 hour'),updated_at=now() where id=s.id; end; end loop; return jsonb_build_object('processed',processed); end; $$;
create or replace function public.reporting_schedule_init() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.next_run_at is null then new.next_run_at:=reporting_next_run(new.cadence,new.hour_local,new.timezone,new.day_of_week,new.day_of_month,now()); end if; return new; end; $$;
drop trigger if exists reporting_schedule_init_trigger on public.reporting_schedules; create trigger reporting_schedule_init_trigger before insert or update of cadence,hour_local,timezone,day_of_week,day_of_month on public.reporting_schedules for each row execute function public.reporting_schedule_init();
revoke all on function public.run_due_reporting_schedules(uuid) from public,anon,authenticated; grant execute on function public.run_due_reporting_schedules(uuid) to service_role;
revoke all on function public.reporting_build_payload(text,uuid,timestamptz,timestamptz) from public,anon,authenticated;
revoke all on function public.reporting_next_run(text,integer,text,integer,integer,timestamptz) from public,anon,authenticated;
select cron.schedule('kleenest-reporting-scheduler','*/15 * * * *',$cmd$select public.run_due_reporting_schedules(null);$cmd$) where not exists (select 1 from cron.job where jobname='kleenest-reporting-scheduler');
